export type ContentType = "Фильм" | "Сериал" | "Аниме" | "Мультфильм" | "Документальный";

export type MovieFact = {
  label: string;
  value: string;
};

export type CastMember = {
  name: string;
  role: string;
};

export type PlayerProvider = {
  id: string;
  name: string;
  embedUrl: string;
  type?: "iframe" | "rendex" | "collapse" | "collapse-iframe" | "vibix-iframe";
  provider?: string;
  publisherId?: string;
  contentType?: string;
  contentId?: string;
  contentKind?: string;
  scriptSrc?: string;
  design?: string;
  color1?: string;
  color2?: string;
  color3?: string;
  color4?: string;
  color5?: string;
};

export type Movie = {
  id: number;
  kinopoiskId?: number;
  slug: string;
  title: string;
  originalTitle: string;
  searchTitles: string[];
  type: ContentType;
  year: string;
  rating: number;
  genres: string[];
  poster: string;
  posterFallbacks?: string[];
  backdrop?: string;
  description: string;
  trailerUrl: string;
  tmdbId?: number;
  imdbId?: string;
  countries?: string[];
  source?: string;
  longDescription?: string;
  facts?: MovieFact[];
  cast?: CastMember[];
  players?: PlayerProvider[];
};

function createKinopoiskPlayers(kinopoiskId: number): PlayerProvider[] {
  const id = String(kinopoiskId);

  return [
    {
      id: `collapse-kp-${id}`,
      name: "Основной",
      type: "collapse",
      provider: "collapse",
      embedUrl: `https://api.ortified.ws/embed/kp/${id}?sharing=false&episodesOpen=false`,
      contentKind: "kp",
      contentType: "kp",
      contentId: id,
    },
    {
      id: `factorios-${id}`,
      name: "Запасной 1",
      type: "iframe",
      provider: "factorios",
      embedUrl: `https://tarantino.factorios.live/show/kinopoisk/${id}`,
    },
  ];
}

function compactMovieText(text: string) {
  return text.replace(/\s+/g, " ").trim();
}

function getFactValueFromMovie(movie: Movie, labels: string[]) {
  const normalizedLabels = labels.map((label) => label.toLowerCase());

  return movie.facts?.find((fact) =>
    normalizedLabels.includes(fact.label.toLowerCase()),
  )?.value;
}

function appendMovieFact(movie: Movie, label: string, value?: string | number | null) {
  if (value === undefined || value === null || value === "") return;

  const textValue = String(value);
  movie.facts = movie.facts ?? [];

  if (movie.facts.some((fact) => fact.label.toLowerCase() === label.toLowerCase())) {
    return;
  }

  movie.facts.push({ label, value: textValue });
}

function getReadableContentType(movie: Movie) {
  if (movie.type === "Сериал") return "сериал";
  if (movie.type === "Аниме") return "аниме";
  if (movie.type === "Мультфильм") return "мультфильм";
  if (movie.type === "Документальный") return "документальный проект";
  if (movie.genres.includes("Анимация")) return "анимационный фильм";
  return "фильм";
}

function createExpandedMovieDescription(movie: Movie) {
  const kind = getReadableContentType(movie);
  const genres = movie.genres.length > 0 ? movie.genres.join(", ").toLowerCase() : "кино";
  const country = movie.countries?.join(", ") || getFactValueFromMovie(movie, ["Страна", "Страны"]);
  const duration = getFactValueFromMovie(movie, ["Длительность", "Хронометраж"]);
  const director = getFactValueFromMovie(movie, ["Режиссёр", "Режиссёры", "Создатель", "Создатели"]);
  const studio = getFactValueFromMovie(movie, ["Студия"]);
  const rating = movie.rating > 0 ? `Рейтинг — ${movie.rating.toFixed(1)} из 10.` : "Рейтинг появится после обновления карточки.";
  const heroes = movie.cast && movie.cast.length > 0
    ? movie.cast.slice(0, 5).map((person) => `${person.name} — ${person.role}`).join(", ")
    : getFactValueFromMovie(movie, ["Главные герои", "Главные персонажи"]);
  const factualParts = [
    country ? `страна: ${country}` : "",
    duration ? `длительность: ${duration}` : "",
    director ? `режиссура/создатели: ${director}` : "",
    studio ? `студия: ${studio}` : "",
  ].filter(Boolean).join("; ");

  const firstParagraph = `«${movie.title}» (${movie.year}) — ${kind} в жанрах ${genres}. ${movie.description}`;
  const secondParagraph = factualParts
    ? `В карточке указаны проверяемые сведения: ${factualParts}. ${heroes ? `В центре внимания: ${heroes}.` : "Информация о героях и актёрах отображается, если она добавлена в карточку."}`
    : `${heroes ? `В центре внимания: ${heroes}.` : "Карточка не выдумывает детали: дополнительные сведения появляются только тогда, когда они уже есть в каталоге."}`;
  const thirdParagraph = `${rating} Этот материал удобно открыть, когда хочется заранее понять настроение, жанры, темп и состав истории перед просмотром. На странице есть краткая карточка, расширенный блок «О фильме», трейлер при наличии и варианты просмотра, если они доступны.`;

  return [firstParagraph, secondParagraph, thirdParagraph]
    .map((part) => compactMovieText(part))
    .join("\n\n");
}

function trimMovieDescription(text: string, maxLength = 940) {
  const paragraphs = text
    .split(/\n{2,}/)
    .map((paragraph) => compactMovieText(paragraph))
    .filter(Boolean);
  const cleanText = paragraphs.join("\n\n");

  if (cleanText.length <= maxLength) return cleanText;

  return `${cleanText.slice(0, maxLength).replace(/\s+\S*$/, "")}.`;
}

function needsPublicLongDescriptionRefresh(value: string | undefined) {
  if (!value) return true;

  return (
    value.length < 560 ||
    /SEO|FAQ-размет|JSON-LD|Kinopoisk|Кинопоиск|TMDB|IMDb|IMDB|источник их отдаёт|страница подготовлена/i.test(value)
  );
}

function containsPublicProviderName(value: string) {
  return /kinopoisk|кинопоиск|tmdb|themoviedb|imdb|\btt\d{5,}\b/i.test(value);
}

function sanitizePublicMovieText(value: string | undefined) {
  if (!value) return value;

  return compactMovieText(
    value
      .replace(/плеерами\s+Collapse\/Factorios\s+по\s+Kinopoisk\s+ID/gi, "вариантами просмотра")
      .replace(/плеерами\s+Collapse\/Factorios\s+по\s+Kinopoisk/gi, "вариантами просмотра")
      .replace(/плеерами\s+по\s+Kinopoisk\s+ID/gi, "вариантами просмотра")
      .replace(/плеерами\s+по\s+Kinopoisk/gi, "вариантами просмотра")
      .replace(/по\s+Kinopoisk\s+ID/gi, "для удобного просмотра")
      .replace(/по\s+Kinopoisk/gi, "для удобного просмотра")
      .replace(/по\s+Кинопоиск\s+ID/gi, "для удобного просмотра")
      .replace(/по\s+Кинопоиску/gi, "для удобного просмотра")
      .replace(/Kinopoisk\s+ID/gi, "каталожный номер")
      .replace(/Кинопоиск\s+ID/gi, "каталожный номер")
      .replace(/IMDb\s+ID/gi, "каталожный номер")
      .replace(/IMDB\s+ID/gi, "каталожный номер")
      .replace(/Kinopoisk/gi, "KinoLuma")
      .replace(/Кинопоиск/gi, "KinoLuma")
      .replace(/TMDB/gi, "KinoLuma")
      .replace(/themoviedb/gi, "KinoLuma")
      .replace(/IMDb/gi, "KinoLuma")
      .replace(/IMDB/gi, "KinoLuma")
      .replace(/Рейтинг\s+KinoLuma/gi, "Рейтинг")
      .replace(/для\s+SEO/gi, "для удобной навигации")
      .replace(/для\s+продвижения/gi, "для удобной навигации")
      .replace(/поисков(?:ая|ую|ой)\s+точк(?:а|у|ой)\s+входа/gi, "подборку")
      .replace(/поисковые\s+страницы/gi, "страницы подборок")
      .replace(/описание,?\s*/gi, "")
      .replace(/описание,?\s*/gi, "")
      .replace(/описание,?\s*/gi, "")
      .replace(/шаблонный\s+SEO(?:-слой)?/gi, "описание")
      .replace(/SEO\/FAQ/gi, "описание")
      .replace(/SEO\s+и\s+FAQ/gi, "описание")
      .replace(/FAQPage\s+JSON-LD/gi, "дополнительные сведения")
      .replace(/JSON-LD/gi, "")
      .replace(/дополнительные сведения\s+и\s+/gi, "")
      .replace(/FAQ\s+через\s+общий\s+шаблон\s+страницы\s+и\s+/gi, "")
      .replace(/,?\s*дополнительные сведения/gi, "")
      .replace(/,?\s*описание/gi, "")
      .replace(/,?\s*описание/gi, "")
      .replace(/,?\s*описание/gi, "")
      .replace(/sitemap,?\s*/gi, "")
      .replace(/служебные данные,?\s*/gi, "")
      .replace(/movies\.ts/gi, "каталог")
      .replace(/серверн(?:ый|ого|ым|ая|ую)?\s+[A-Za-zА-Яа-яёЁ-]+-роут(?:а|ом)?/gi, "внутренний каталог")
      .replace(/если источник их отдаёт/gi, "если информация есть в карточке")
      .replace(/после обновления источников/gi, "после обновления карточки")
      .replace(/источник их отдаёт/gi, "информация есть в карточке")
      .replace(/источников/gi, "данных")
      .replace(/источник/gi, "данные"),
  );
}

function sanitizeMoviePublicFields(movie: Movie) {
  movie.description = sanitizePublicMovieText(movie.description) || movie.description;
  movie.longDescription = sanitizePublicMovieText(movie.longDescription);

  if (movie.facts?.length) {
    movie.facts = movie.facts
      .filter((fact) => !containsPublicProviderName(`${fact.label} ${fact.value}`))
      .map((fact) => ({
        label: sanitizePublicMovieText(fact.label) || fact.label,
        value: sanitizePublicMovieText(fact.value) || fact.value,
      }));
  }

  return movie;
}

export function sanitizeMovieForPublicDisplay(movie: Movie): Movie {
  return sanitizeMoviePublicFields({
    ...movie,
    genres: [...(movie.genres ?? [])],
    searchTitles: [...(movie.searchTitles ?? [])],
    countries: movie.countries ? [...movie.countries] : undefined,
    facts: movie.facts ? movie.facts.map((fact) => ({ ...fact })) : undefined,
    cast: movie.cast ? movie.cast.map((person) => ({ ...person })) : undefined,
    players: movie.players ? movie.players.map((player) => ({ ...player })) : undefined,
    posterFallbacks: movie.posterFallbacks ? [...movie.posterFallbacks] : undefined,
  });
}

function getMoviePosterFallback(movie: Movie) {
  const currentPoster =
    movie.poster &&
    !movie.poster.startsWith("data:") &&
    !movie.poster.includes("/api/kinopoisk/poster")
      ? movie.poster
      : "";

  const tmdbPoster = getTmdbPoster({
    tmdbId: movie.tmdbId,
    imdbId: movie.imdbId,
    title: movie.title,
    originalTitle: movie.originalTitle,
    year: movie.year,
    type: movie.type,
  });

  return currentPoster || tmdbPoster;
}

function hydrateMovieContent(movie: Movie) {
  appendMovieFact(movie, "Год", movie.year);
  appendMovieFact(movie, "Тип", movie.type);
  appendMovieFact(movie, "Жанры", movie.genres.join(", "));

  if (movie.kinopoiskId) {
    const fallbackPoster = getMoviePosterFallback(movie);
    movie.poster = getKinopoiskPoster({
      kinopoiskId: movie.kinopoiskId,
      fallback: fallbackPoster,
    });

    if (fallbackPoster) {
      movie.posterFallbacks = Array.from(
        new Set([...(movie.posterFallbacks ?? []), fallbackPoster]),
      );
    }
  }

  if (movie.rating > 0) {
    appendMovieFact(movie, "Рейтинг", movie.rating.toFixed(1));
  }

  if (movie.cast && movie.cast.length > 0) {
    appendMovieFact(
      movie,
      "Главные герои",
      movie.cast.slice(0, 5).map((person) => `${person.name} — ${person.role}`).join(", "),
    );
  }

  if (movie.kinopoiskId && (!movie.players || movie.players.length === 0)) {
    const kinopoiskPlayers = createKinopoiskPlayers(movie.kinopoiskId);
    movie.players = movie.type === "Аниме" ? kinopoiskPlayers.slice(0, 1) : kinopoiskPlayers;
  }

  if (needsPublicLongDescriptionRefresh(movie.longDescription)) {
    movie.longDescription = trimMovieDescription(createExpandedMovieDescription(movie));
  }
}

